import {t,getLocale} from './locales.js';import {COW} from './cow-config.js';import {cowUpgradeReason,COW_UPGRADES} from './cow-upgrades.js';
/** @param {import('./engine.js').State} state @param {import('./cow-panel.js').CowSend} send @param {HTMLElement} host */
export function renderCowUpgrades(state,send,host){const g=state.cow;if(!g?.visited)return;const section=document.createElement('section'),heading=document.createElement('h3'),goal=document.createElement('button');section.id='cow-upgrades';heading.textContent=t('cowNextUpgrade');goal.type='button';goal.id='view-cow-upgrade';goal.className='action-button';goal.textContent=t('cowViewGoal');goal.disabled=g.mission.upgradeViewed;goal.addEventListener('click',()=>send('viewCowUpgrade'));section.append(heading,goal);if(g.mission.upgradeViewed){const copy=document.createElement('p'),shortfall=document.createElement('p'),buy=document.createElement('button'),reason=cowUpgradeReason(state,'buyCowTrough');copy.id='cow-upgrade-benefit';copy.textContent=t('cowLargerTrough')+' · '+COW.troughPrice+' '+t('coins')+'. '+t('cowTroughBenefit');shortfall.id='cow-upgrade-shortfall';shortfall.textContent=t('cowGoalShortfall')+': '+Math.max(0,COW.troughPrice-state.coins).toLocaleString(getLocale())+' '+t('coins');buy.type='button';buy.id='buy-cow-trough';buy.className='action-button primary';buy.textContent=t(g.barn?.troughUpgrade?'cowUpgradeOwned':'cowBuyUpgrade');buy.disabled=!!reason;buy.title=reason?t(reason):'';buy.addEventListener('click',event=>{if(event.detail>1)return;send('buyCowTrough');});section.append(copy,shortfall,buy);}if(g.mission.step>=8){const details=document.createElement('details'),summary=document.createElement('summary');details.id='cow-advanced-upgrades';summary.textContent=t('cowFurtherUpgrades');details.append(summary);appendCowUpgrade(state,send,details,'buyCowShade','cowShade','cowShadeBenefit','buy-cow-shade');section.append(details);}host.append(section);}

/** @param {import('./engine.js').State} state @param {import('./cow-panel.js').CowSend} send @param {HTMLElement} host @param {keyof typeof COW_UPGRADES} type @param {string} title @param {string} help @param {string} id */
export function appendCowUpgrade(state,send,host,type,title,help,id){const choice=COW_UPGRADES[type],reason=cowUpgradeReason(state,type),row=document.createElement('div'),heading=document.createElement('h4'),copy=document.createElement('p'),button=document.createElement('button'),note=document.createElement('p');heading.textContent=t(title)+' · '+choice.price+' '+t('coins');copy.textContent=t(help);button.id=id;button.type='button';button.className='action-button';button.textContent=t(reason==='cowUpgradeOwned'?'cowUpgradeOwned':'cowBuyEquipment');button.disabled=!!reason;button.addEventListener('click',event=>{if(event.detail>1)return;send(type);});note.textContent=reason?t(reason):t('cowGoalShortfall')+': 0 '+t('coins');row.append(heading,copy,button,note);host.append(row);}
